import java.util.*;
import java.io.*;

public class Main {
    static class Step implements Comparable<Step> {
        long val;
        int cost;

        Step(long val, int cost) {
            this.val = val;
            this.cost = cost;
        }

        @Override
        public int compareTo(Step c) {
            // PriorityQueue in Java is a min-heap, so to mimic the C++ code's behavior,
            // we need to compare such that the step with the smaller cost has higher priority.
            return Integer.compare(this.cost, c.cost);
        }
    }

    static Set<Long> visited = new HashSet<>();

    static boolean hasVisited(long c) {
        return visited.contains(c);
    }

    static Step getUpperBound(long n) {
        long res = 0;
        int i = 0;
        while (res < n) {
            res = res * 10 + 1;
            i++;
        }
        return new Step(res, i);
    }

    static Step getUpper(long n) {
        long res = 0;
        int i = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            i++;
        }
        long resmul = res;
        int imul = i;
        while (res < n) {
            res += resmul;
            i += imul;
        }
        return new Step(res, i);
    }

    static Step getLower(long n) {
        long res = 0;
        int i = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            i++;
        }
        long resmul = res;
        int imul = i;
        while (res + resmul <= n) {
            res += resmul;
            i += imul;
        }
        return new Step(res, i);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());

        PriorityQueue<Step> pq = new PriorityQueue<>();
        pq.add(new Step(n, 0));

        while (pq.peek().val != 0) {
            Step current = pq.poll();
            long val = current.val;
            int cost = current.cost;

            if (hasVisited(val))
                continue;
            visited.add(val);

            for (Step s : Arrays.asList(getLower(val), getUpper(val), getUpperBound(val))) {
                s.cost += cost;
                s.val = Math.abs(val - s.val);
                pq.add(s);
            }
        }

        System.out.println(pq.peek().cost);
    }
}
